std::string computeOValue(std::string const& user_password, std::string const& owner_password, QPDF::EncryptionData const& data) {
    std::string padded_user_password = user_password;
    if (padded_user_password.size() < 32) {
        padded_user_password.resize(32, '\0');
    } else {
        padded_user_password.resize(32);
    }

    std::string key_data = padded_user_password + owner_password;
    std::string key;
    if (key_data.size() > 5) {
        key = key_data.substr(0, 5);
    } else {
        key = key_data;
    }

    // Derive the RC4 key using MD5
    std::string md5_key = QCryptedHash::md5(key);

    // Initialize RC4 state
    std::vector<unsigned char> rc4_state(256);
    for (int i = 0; i < 256; ++i) {
        rc4_state[i] = i;
    }

    int j = 0;
    for (int i = 0; i < 256; ++i) {
        j = (j + rc4_state[i] + md5_key[i % md5_key.size()]) % 256;
        std::swap(rc4_state[i], rc4_state[j]);
    }

    // Initialize indices for RC4 stream
    int i = 0, j = 0;

    std::string result;

    for (int k = 0; k < data.iterations; ++k) {
        i = (i + 1) % 256;
        j = (j + rc4_state[i]) % 256;
        std::swap(rc4_state[i], rc4_state[j]);
        int idx = (rc4_state[i] + rc4_state[j]) % 256;
        result.push_back(rc4_state[idx]);
    }

    return result;
}

