#include <string>
#include <openssl/rc4.h>

std::string compute_O_value(std::string const& user_password, std::string const& owner_password, QPDF::EncryptionData const& data)
{
    // Derive RC4 key from user and owner passwords
    RC4_KEY key;
    RC4_set_key(&key, user_password.size() + owner_password.size(), reinterpret_cast<const unsigned char*>(user_password.c_str()), reinterpret_cast<const unsigned char*>(owner_password.c_str()));

    // Pad or truncate the user password as necessary
    std::string padded_user_password = user_password;
    if (padded_user_password.size() < 32) {
        padded_user_password.resize(32, '\0');
    } else {
        padded_user_password.resize(32);
    }

    // Initialize RC4 state
    RC4_KEY rc4_state;
    RC4_set_key(&rc4_state, 32, reinterpret_cast<const unsigned char*>(padded_user_password.c_str()));

    // Apply the RC4 encryption iteratively
    unsigned char output[32] = { 0 };
    RC4(&rc4_state, 32, reinterpret_cast<const unsigned char*>(padded_user_password.c_str()), output);

    // Convert the result to a string and return
    return std::string(reinterpret_cast<char*>(output), 32);
}
